const topic = msg.topic || '';
let body = msg.payload;
if (Buffer.isBuffer(body)) body = body.toString();
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* availability is plain text */ } }
const received = new Date().toISOString();
const view = {topic, data: body, received_at: received};
const events = [];
if (topic.endsWith('/telemetry')) {
  flow.set('orchidTelemetryAt', Date.now());
  flow.set('orchidStaleLogged', false);
} else if (topic.endsWith('/availability')) {
  const wasOnline = flow.get('orchidOnline');
  flow.set('orchidOnline', body);
  if (body === 'offline' && wasOnline !== 'offline') flow.set('orchidOfflineSince', Date.now());
  if (body === 'online') {
    flow.set('orchidOfflineSince', 0);
    flow.set('orchidOfflineFiveMinuteLogged', false);
  }
  if ((body === 'online' || body === 'offline') && wasOnline !== body) events.push({event:'availability', state:body, at:received});
} else if (topic.endsWith('/state') && body && typeof body === 'object') {
  const current = {mist:body.mist, fan:body.fan, light:body.light};
  const previous = flow.get('orchidRelayState');
  if (previous) for (const relay of ['mist','fan','light']) {
    if (current[relay] !== undefined && previous[relay] !== current[relay]) events.push({event:'relay_change', relay, from:previous[relay], to:current[relay], at:received});
  }
  flow.set('orchidRelayState', current);
}
const history = events.map(e => ({payload:JSON.stringify(e)+'\n'}));
return [{payload:view}, history.length ? history : null];

const now = Date.now();
const online = flow.get('orchidOnline');
let seen = flow.get('orchidTelemetryAt') || 0;
const alerts = [];
if (online === 'offline') {
  let offlineSince = flow.get('orchidOfflineSince') || 0;
  if (!offlineSince) { offlineSince = now; flow.set('orchidOfflineSince', offlineSince); }
  if (!flow.get('orchidOfflineFiveMinuteLogged') && now - offlineSince >= 300000) {
    alerts.push({event:'device_offline_over_5m', duration_s:Math.floor((now-offlineSince)/1000), at:new Date(now).toISOString()});
    flow.set('orchidOfflineFiveMinuteLogged', true);
  }
} else if (online === 'online') {
  flow.set('orchidOfflineSince', 0);
  flow.set('orchidOfflineFiveMinuteLogged', false);
  if (!seen) { seen = now; flow.set('orchidTelemetryAt', seen); }
}
if (online === 'offline' && !flow.get('orchidOfflineLogged')) { alerts.push({event:'device_offline', at:new Date(now).toISOString()}); flow.set('orchidOfflineLogged', true); }
if (online === 'online') flow.set('orchidOfflineLogged', false);
if (seen && now - seen > 15000 && !flow.get('orchidStaleLogged')) { alerts.push({event:'telemetry_stale', age_s:Math.floor((now-seen)/1000), at:new Date(now).toISOString()}); flow.set('orchidStaleLogged', true); }
return alerts.map(a => ({payload:JSON.stringify(a)+'\n'}));

let data = msg.payload;
if (Buffer.isBuffer(data)) data = data.toString();
if (typeof data === 'string') { try { data = JSON.parse(data); } catch (err) { node.warn('Invalid telemetry JSON'); return null; } }
if (!data || typeof data !== 'object') return null;
const now = new Date().toISOString();
const events = [];
function numeric(value) {
  if (value === null || value === undefined || value === '') return NaN;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : NaN;
}
function evaluate(key, metric, value, onAt, offAt) {
  const previous = flow.get(key) === true;
  const active = previous ? value >= offAt : value > onAt;
  if (active !== previous) {
    flow.set(key, active);
    events.push({event:active ? 'threshold_active' : 'threshold_cleared', rule:key, metric, value, threshold:active ? onAt : offAt, at:now});
  }
}
const temperature = numeric(data.temperature_c);
if (Number.isFinite(temperature)) evaluate('orchidHighTemperature', 'temperature_c', temperature, 33, 31);
const humidity = numeric(data.humidity_pct);
if (Number.isFinite(humidity)) evaluate('orchidHighHumidity', 'humidity_pct', humidity, 90, 85);
const lightAdc = numeric(data.light_adc);
if (Number.isFinite(lightAdc)) evaluate('orchidLightDemand', 'light_adc', lightAdc, 2200, 1800);
return events.length ? [{payload:events.map(e => JSON.stringify(e)+'\n').join(''), events}] : null;

let data = msg.payload;
if (Buffer.isBuffer(data)) data = data.toString();
if (typeof data === 'string') { try { data = JSON.parse(data); } catch (err) { node.warn('Invalid telemetry JSON'); return null; } }
if (!data || typeof data !== 'object') return null;
const now = new Date().toISOString();
const events = [];
function numeric(value) {
  if (value === null || value === undefined || value === '') return NaN;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : NaN;
}
const water = numeric(data.water_adc);
const humidity = numeric(data.humidity_pct);
let waterLow = flow.get('orchidWaterLow');
if (Number.isFinite(water)) {
  if (waterLow === undefined) {
    waterLow = water < 1200;
    if (waterLow) events.push({event:'water_lockout', water_adc:water, threshold:1200, at:now});
  } else {
    const nextWaterLow = waterLow ? water < 1500 : water < 1200;
    if (nextWaterLow !== waterLow) events.push({event:nextWaterLow ? 'water_lockout' : 'water_recovered', water_adc:water, threshold:nextWaterLow ? 1200 : 1500, at:now});
    waterLow = nextWaterLow;
  }
  flow.set('orchidWaterLow', waterLow);
}
if (Number.isFinite(humidity) && Number.isFinite(water)) {
  const previousDemand = flow.get('orchidMistDemand') === true;
  const mistDemand = waterLow ? false : previousDemand ? humidity < 80 : humidity < 65;
  if (mistDemand !== previousDemand) {
    flow.set('orchidMistDemand', mistDemand);
    events.push({event:mistDemand ? 'mist_demand_observed' : 'mist_demand_cleared', humidity_pct:humidity, water_adc:water, at:now});
  }
}
return events.length ? [{payload:events.map(e => JSON.stringify(e)+'\n').join(''), events}] : null;

const inputTopic = msg.topic || '';
let data = msg.payload;
if (inputTopic !== 'dashboard/refresh') {
  if (data && typeof data === 'object' && data.data !== undefined) data = data.data;
  if (Buffer.isBuffer(data)) data = data.toString();
  if (typeof data === 'string' && !inputTopic.endsWith('/availability')) {
    try { data = JSON.parse(data); } catch (err) { node.warn('Invalid dashboard MQTT JSON'); return null; }
  }
}
const snapshot = flow.get('orchidDashboardSnapshot') || {
  temperature_c: null, humidity_pct: null, light_adc: null, water_adc: null,
  mist: '—', fan: '—', light: '—', mist_state: '—', mode: '—', availability: 'unknown'
};
let telemetryUpdate = false;
if (inputTopic.endsWith('/telemetry') && data && typeof data === 'object') {
  for (const key of ['temperature_c','humidity_pct','light_adc','water_adc']) {
    if (data[key] !== undefined && Number.isFinite(Number(data[key]))) snapshot[key] = Number(data[key]);
  }
  flow.set('orchidDashboardTelemetryAt', Date.now());
  snapshot.availability = 'online';
  telemetryUpdate = true;
} else if (inputTopic.endsWith('/state') && data && typeof data === 'object') {
  for (const key of ['mist','fan','light','mist_state','mode']) {
    if (data[key] !== undefined) snapshot[key] = String(data[key]);
  }
  if (data.water_lockout === true) snapshot.mist_state = 'WATER_LOCKOUT';
} else if (inputTopic.endsWith('/availability')) {
  const availability = typeof data === 'string' ? data : String(data);
  if (availability === 'online' || availability === 'offline') snapshot.availability = availability;
}
flow.set('orchidDashboardSnapshot', snapshot);
const lastTelemetry = flow.get('orchidDashboardTelemetryAt') || 0;
const isStale = lastTelemetry > 0 && Date.now() - lastTelemetry > 15000;
const connection = snapshot.availability === 'offline' ? 'OFFLINE' : isStale ? 'STALE' : snapshot.availability === 'online' ? 'ONLINE' : 'WAITING';
const show = (value, suffix) => value === null ? '—' : `${value}${suffix}`;
const climateHistory = telemetryUpdate ? [
  {topic:'Temperature °C', payload:snapshot.temperature_c},
  {topic:'Humidity %', payload:snapshot.humidity_pct}
].filter(point => Number.isFinite(point.payload)) : null;
const adcHistory = telemetryUpdate ? [
  {topic:'Light ADC', payload:snapshot.light_adc},
  {topic:'Water ADC', payload:snapshot.water_adc}
].filter(point => Number.isFinite(point.payload)) : null;
const mistDisplay = snapshot.mist === 'ON' ? 'ON' : (snapshot.mist_state === 'WATER_LOCKOUT' ? 'WATER_LOCKOUT' : (snapshot.mode === 'MANUAL' ? 'OFF (MANUAL)' : snapshot.mist_state));
return [
  {payload:show(snapshot.temperature_c, ' °C')},
  {payload:show(snapshot.humidity_pct, ' %')},
  {payload:show(snapshot.light_adc, '')},
  {payload:show(snapshot.water_adc, '')},
  {payload:mistDisplay},
  {payload:snapshot.fan},
  {payload:snapshot.light},
  {payload:connection},
  {payload:snapshot.mode},
  climateHistory,
  adcHistory
];

const topic = msg.topic || '';
let body = msg.payload;
if (Buffer.isBuffer(body)) body = body.toString();
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (err) { node.warn('Invalid telemetry JSON'); return null; } }
if (topic.endsWith('/telemetry') && body && typeof body === 'object' && Number.isFinite(Number(body.light_adc))) flow.set('orchidWeek7LightAdc', Number(body.light_adc));
const lightAdc = flow.get('orchidWeek7LightAdc');
if (!Number.isFinite(lightAdc)) return null;
const settings = {start:'08:00', end:'20:00', darkAdcOn:2200};
const testTime = msg.testTime || (body && typeof body === 'object' && body.test_time);
const now = testTime ? new Date(`2026-10-09T${testTime}:00`) : new Date();
const minute = now.getHours() * 60 + now.getMinutes();
const toMinutes = value => { const [hours, minutes] = value.split(':').map(Number); return hours * 60 + minutes; };
const inSchedule = minute >= toMinutes(settings.start) && minute < toMinutes(settings.end);
const recommendation = inSchedule && lightAdc > settings.darkAdcOn ? 'ON' : 'OFF';
const previous = flow.get('orchidWeek7LightRecommendation');
if (previous === recommendation) return null;
flow.set('orchidWeek7LightRecommendation', recommendation);
const event = {event:'automation_recommendation', rule:'daytime_light_schedule', action:recommendation, light_adc:lightAdc, schedule:`${settings.start}-${settings.end}`, at:now.toISOString()};
return {payload:JSON.stringify(event)+'\n', event};

const topic = msg.topic || '';
let body = msg.payload;
if (Buffer.isBuffer(body)) body = body.toString();
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (err) { node.warn('Invalid state JSON'); return null; } }
const nowMs = Date.now();
const testTime = msg.testTime;
const timestamp = testTime ? new Date(testTime).toISOString() : new Date(nowMs).toISOString();
const events = [];
if (topic.endsWith('/state') && body && typeof body === 'object') {
  const nextMistState = body.mist_state;
  const previousMistState = flow.get('orchidWeek7MistState');
  if (nextMistState !== undefined && previousMistState === 'RUNNING' && ['IDLE','COOLDOWN'].includes(nextMistState)) {
    const fanWasOn = body.fan === 'ON';
    flow.set('orchidWeek7FanAssistUntil', nowMs + 180000);
    if (!fanWasOn) events.push({event:'automation_recommendation', rule:'fan_after_mist', action:'ON', duration_s:180, reason:'mist_cycle_finished', at:timestamp});
  }
  if (nextMistState !== undefined) flow.set('orchidWeek7MistState', nextMistState);
}
const assistUntil = flow.get('orchidWeek7FanAssistUntil') || 0;
if (assistUntil && nowMs >= assistUntil) {
  flow.set('orchidWeek7FanAssistUntil', 0);
  events.push({event:'automation_recommendation', rule:'fan_after_mist', action:'OFF', reason:'assist_window_expired', at:timestamp});
}
return events.length ? events.map(event => ({payload:JSON.stringify(event)+'\n', event})) : null;

const topic = msg.topic || '';
let body = msg.payload;
if (Buffer.isBuffer(body)) body = body.toString();
if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { /* chuỗi thuần như online/offline */ }
}
const received = new Date().toISOString();
const view = { topic, data: body, received_at: received };
const historyEvents = [];
const alertEvents = [];
const automationTriggers = [];

// 1. Xử lý Telemetry
if (topic.endsWith('/telemetry') && typeof body === 'object' && body !== null) {
    flow.set('orchidTelemetryAt', Date.now());
    flow.set('orchidStaleLogged', false);
    flow.set('orchidLatestTelemetry', body);

    // Kiểm tra cảm biến DHT22
    if (body.temperature_c === null || body.temperature_c === undefined) {
        let dhtRejects = (flow.get('orchidDhtFaultCount') || 0) + 1;
        flow.set('orchidDhtFaultCount', dhtRejects);
        if (dhtRejects >= 3 && !flow.get('orchidDhtAlertSent')) {
            alertEvents.push({
                type: 'DHT_FAULT',
                severity: 'HIGH',
                title: 'LỖI CẢM BIẾN DHT22',
                message: 'Cảm biến DHT22 không trả về dữ liệu (null/NaN) liên tiếp 3 chu kỳ! Hệ thống chuyển sang chế độ phòng vệ.',
                at: received
            });
            flow.set('orchidDhtAlertSent', true);
        }
    } else {
        flow.set('orchidDhtFaultCount', 0);
        flow.set('orchidDhtAlertSent', false);

        // Kiểm tra nhiệt độ cao
        if (body.temperature_c >= 33.0) {
            const lastTempAlert = flow.get('orchidLastTempAlertAt') || 0;
            if (Date.now() - lastTempAlert > 5 * 60 * 1000) { // debounce 5 phút
                alertEvents.push({
                    type: 'HIGH_TEMPERATURE',
                    severity: 'HIGH',
                    title: 'CẢNH BÁO NHIỆT ĐỘ CAO',
                    message: 'Nhiệt độ hiện tại: ' + body.temperature_c.toFixed(1) + '°C (vượt ngưỡng 33.0°C). Cần kích hoạt quạt làm mát.',
                    temperature: body.temperature_c,
                    at: received
                });
                flow.set('orchidLastTempAlertAt', Date.now());
            }
        }
    }

    // Kiểm tra mực nước thấp (water_adc < 1200)
    if (body.water_adc !== undefined) {
        flow.set('orchidLatestWaterAdc', body.water_adc);
        if (body.water_adc < 1200) {
            if (!flow.get('orchidWaterLowAlertSent')) {
                alertEvents.push({
                    type: 'WATER_LOW',
                    severity: 'CRITICAL',
                    title: 'CẢNH BÁO CẠN NƯỚC',
                    message: 'Mực nước bình chứa đang ở mức THẤP (ADC: ' + body.water_adc + ' < 1200)! Phun sương bị khóa an toàn (WATER_LOCKOUT).',
                    water_adc: body.water_adc,
                    at: received
                });
                flow.set('orchidWaterLowAlertSent', true);
            }
        } else if (body.water_adc >= 1500) {
            // Nước đã được châm đầy lại
            if (flow.get('orchidWaterLowAlertSent')) {
                flow.set('orchidWaterLowAlertSent', false);
                alertEvents.push({
                    type: 'WATER_REFILLED',
                    severity: 'INFO',
                    title: 'MỰC NƯỚC ĐÃ PHỤC HỒI',
                    message: 'Bình chứa đã được châm nước đầy (ADC: ' + body.water_adc + '). Hệ thống sẵn sàng hoạt động trở lại.',
                    at: received
                });
            }
        }
    }
}
// 2. Xử lý Trạng thái State & Relay transitions
else if (topic.endsWith('/state') && typeof body === 'object' && body !== null) {
    const current = { mist: body.mist, fan: body.fan, light: body.light, mist_state: body.mist_state, water_lockout: body.water_lockout, mode: body.mode };
    const previous = flow.get('orchidRelayState');

    if (previous) {
        for (const relay of ['mist', 'fan', 'light']) {
            if (current[relay] !== undefined && previous[relay] !== current[relay]) {
                historyEvents.push({
                    event: 'relay_change',
                    relay: relay,
                    from: previous[relay],
                    to: current[relay],
                    at: received
                });
            }
        }

        // Tự động hóa Tuần 7: Quạt hỗ trợ sau chu kỳ phun (Post-Mist Fan Ventilation)
        // Khi mist chuyển từ ON -> OFF (kết thúc phun)
        if (previous.mist === 'ON' && current.mist === 'OFF') {
            automationTriggers.push({
                rule: 'POST_MIST_VENTILATION',
                reason: 'Chu kỳ phun sương vừa kết thúc. Cần bật quạt 60s để hong ráo lá lan.',
                at: received
            });
        }

        // Cảnh báo Water Lockout
        if (current.water_lockout && !previous.water_lockout) {
            alertEvents.push({
                type: 'WATER_LOCKOUT',
                severity: 'CRITICAL',
                title: 'KHÓA NƯỚC AN TOÀN (WATER LOCKOUT)',
                message: 'Firmware ESP32 đã kích hoạt cờ WATER_LOCKOUT. Bơm phun sương bị cưỡng bức ngắt hoàn toàn.',
                at: received
            });
        }
    }
    flow.set('orchidRelayState', current);
}
// 3. Xử lý Availability (Last Will / Online)
else if (topic.endsWith('/availability')) {
    const wasOnline = flow.get('orchidOnline');
    flow.set('orchidOnline', body);
    if ((body === 'online' || body === 'offline') && wasOnline !== body) {
        historyEvents.push({ event: 'availability', state: body, at: received });
        if (body === 'offline') {
            alertEvents.push({
                type: 'DEVICE_OFFLINE',
                severity: 'CRITICAL',
                title: 'MẤT KẾT NỐI ESP32 (OFFLINE)',
                message: 'Broker nhận bản tin Last Will: ESP32 orchid-01 đã ngắt kết nối đột ngột!',
                at: received
            });
        } else if (body === 'online') {
            alertEvents.push({
                type: 'DEVICE_ONLINE',
                severity: 'INFO',
                title: 'ESP32 ĐÃ KẾT NỐI LẠI',
                message: 'Trạm giám sát orchid-01 đã trực tuyến và bắt đầu truyền dữ liệu.',
                at: received
            });
        }
    }
}
// 4. Xử lý ACK từ Firmware
else if (topic.endsWith('/ack') && typeof body === 'object' && body !== null) {
    flow.set('orchidLatestAck', body);
    historyEvents.push({
        event: 'ack_received',
        request_id: body.request_id,
        result: body.result,
        reason: body.reason || '',
        at: received
    });

    if (body.result === 'REJECTED') {
        alertEvents.push({
            type: 'COMMAND_REJECTED',
            severity: 'WARNING',
            title: 'LỆNH BỊ TỪ CHỐI (REJECTED)',
            message: 'Lệnh [' + body.request_id + '] bị ESP32 từ chối vì lý do an toàn: ' + (body.reason || 'UNKNOWN'),
            request_id: body.request_id,
            reason: body.reason,
            at: received
        });
    }
}

// Chuẩn bị các đầu ra
const outDebug = { payload: view };
const outHistory = historyEvents.map(e => ({ payload: JSON.stringify(e) + '\n' }));
const outAlerts = alertEvents.map(a => ({ payload: a }));
const outTriggers = automationTriggers.map(t => ({ payload: t }));

// Output 1: Debug Telemetry
// Output 2: Ghi file lịch sử
// Output 3: Kênh Cảnh báo (Alerts -> Telegram & Dashboard)
// Output 4: Triggers Tự động hóa (Automation Engine)
return [
    outDebug,
    outHistory.length > 0 ? outHistory : null,
    outAlerts.length > 0 ? outAlerts : null,
    outTriggers.length > 0 ? outTriggers : null
];

const now = Date.now();
const online = flow.get('orchidOnline');
let seen = flow.get('orchidTelemetryAt') || 0;
const alerts = [];

if (online === 'offline' && !flow.get('orchidOfflineLogged')) {
    alerts.push({
        type: 'DEVICE_OFFLINE',
        severity: 'CRITICAL',
        title: 'MẤT KẾT NỐI THIẾT BỊ',
        message: 'Trạng thái MQTT: ESP32 orchid-01 đang offline!',
        at: new Date(now).toISOString()
    });
    flow.set('orchidOfflineLogged', true);
}
if (online === 'online') {
    flow.set('orchidOfflineLogged', false);
    if (!seen) {
        seen = now;
        flow.set('orchidTelemetryAt', seen);
    }
}
if (seen && now - seen > 15000 && !flow.get('orchidStaleLogged')) {
    const ageSeconds = Math.floor((now - seen) / 1000);
    alerts.push({
        type: 'TELEMETRY_STALE',
        severity: 'WARNING',
        title: 'DỮ LIỆU TELEMETRY QUÁ HẠN',
        message: 'Đã hơn ' + ageSeconds + ' giây không nhận được dữ liệu cảm biến mới từ trạm.',
        age_s: ageSeconds,
        at: new Date(now).toISOString()
    });
    flow.set('orchidStaleLogged', true);
}

return alerts.map(a => ({ payload: a }));

const now = Date.now();
const online = flow.get("orchidOnline");
const offlineSince = flow.get("orchidOfflineSince");

if (online === "offline") {
    if (!offlineSince) {
        flow.set("orchidOfflineSince", now);
    } else if (now - offlineSince >= 5 * 60 * 1000 && !flow.get("orchid5MinAlertSent")) {
        flow.set("orchid5MinAlertSent", true);
        return {
            payload: {
                type: "OFFLINE_5MIN",
                severity: "CRITICAL",
                title: "BÁO ĐỘNG KHẨN CẤP: MẤT KẾT NỐI QUÁ 5 PHÚT",
                message: "Thiết bị ESP32 (orchid-01) đã mất kết nối liên tục hơn 5 phút. Vui lòng kiểm tra trạm ngay lập tức!",
                at: new Date(now).toISOString()
            }
        };
    }
} else {
    flow.set("orchidOfflineSince", null);
    flow.set("orchid5MinAlertSent", false);
}
return null;

const alert = msg.payload;
if (!alert || typeof alert !== 'object') return null;

// Ghi log lịch sử cảnh báo
const historyLine = JSON.stringify({ event: 'system_alert', alert: alert, at: alert.at || new Date().toISOString() }) + '\n';

// Soạn định dạng hiển thị Dashboard / Debug
const debugMsg = {
    payload: {
        SEVERITY: alert.severity || 'INFO',
        TITLE: alert.title || 'CẢNH BÁO HỆ THỐNG',
        MESSAGE: alert.message,
        TIME: alert.at
    }
};

// Soạn tin nhắn Telegram
const telegramText = 
    "🌿 <b>[ORCHID SMART SYSTEM]</b>\n" +
    "🚨 <b>" + (alert.title || "CẢNH BÁO") + "</b>\n" +
    "⚠️ Mức độ: <code>" + (alert.severity || "INFO") + "</code>\n" +
    "📝 Nội dung: " + alert.message + "\n" +
    "🕒 Thời gian: <i>" + (alert.at || new Date().toLocaleString()) + "</i>";

const telegramMsg = {
    payload: {
        text: telegramText,
        raw_alert: alert
    }
};

// Output 1: Debug Dashboard
// Output 2: Append vào file lịch sử
// Output 3: Telegram Filter & Sender
return [ debugMsg, { payload: historyLine }, telegramMsg ];

// CẤU HÌNH BẢO MẬT TELEGRAM BOT
// 1. Token bot: Lấy từ Environment Variable hoặc biến context, KHÔNG hardcode bí mật công khai.
const botToken = env.get("TELEGRAM_BOT_TOKEN") || flow.get("telegram_token") || "YOUR_TELEGRAM_BOT_TOKEN_HERE";

// 2. Chat ID nhóm được cấp phép (Whitelist): Chỉ cho phép chat ID của nhóm nhận tin
const authorizedChatId = env.get("TELEGRAM_GROUP_CHAT_ID") || flow.get("telegram_group_chat_id") || "-1001234567890";

const incomingText = msg.payload && msg.payload.text ? msg.payload.text : "Cảnh báo không xác định";

// Nếu chưa cấu hình token thật, in cảnh báo giả lập và dừng để tránh spam lỗi HTTP 404/401
if (botToken === "YOUR_TELEGRAM_BOT_TOKEN_HERE" || !botToken) {
    node.warn("[TELEGRAM DEMO] Bot token chưa được cấu hình. Nội dung gửi: " + incomingText);
    return null;
}

// Chuẩn bị request HTTP chuẩn gửi đến Telegram Bot API
msg.url = "https://api.telegram.org/bot" + botToken + "/sendMessage";
msg.method = "POST";
msg.headers = {
    "Content-Type": "application/json"
};
msg.payload = {
    chat_id: authorizedChatId,
    text: incomingText,
    parse_mode: "HTML"
};

return msg;

// FORMAT PAYLOAD ĐÚNG 100% VỚI FIRMWARE ESP32 HIỆN TẠI
// Payload yêu cầu:
// - request_id: chuỗi duy nhất (VD: req-mist-1729123456789)
// - mode: "MANUAL" hoặc "AUTO"
// - state: "ON" hoặc "OFF" (khi mode === "MANUAL")
// - ttl_s: số nguyên từ 1 đến 3600 (khi mode === "MANUAL")

const input = msg.payload || {};
const relay = msg.relay || input.relay || 'mist';
const mode = input.mode || 'AUTO';
const state = input.state ? String(input.state).toUpperCase() : 'ON';
const ttl_s = Number(input.ttl_s) || 60;

const reqId = 'req-' + relay + '-' + (mode === 'AUTO' ? 'auto' : state.toLowerCase()) + '-' + Date.now();

let payload = {
    request_id: reqId,
    mode: mode
};

if (mode === 'MANUAL') {
    payload.state = state;
    payload.ttl_s = ttl_s;
}

msg.topic = 'garden/orchid/orchid-01/cmd/' + relay;
msg.payload = payload;

// Lưu request_id vào context để theo dõi ACK
flow.set('last_sent_request_id', reqId);
return msg;

// BUSINESS RULE 1: ĐIỀU KHIỂN ĐÈN THEO KHUNG GIỜ VÀ ÁNH SÁNG
// Quy tắc ban đêm đã thống nhất:
// 1. Không bật đèn xuyên đêm (từ 21:00 đến 06:00 sáng bắt buộc tắt/AUTO để đảm bảo pha tối cho lan).
// 2. Trong khung giờ quang chu kỳ (06:00 đến 21:00):
//    - Nếu thiếu sáng (light_adc >= 2200): Gửi lệnh bật đèn MANUAL với ttl_s = 300 (5 phút).
//    - Nếu đủ sáng (light_adc <= 1800): Chuyển về AUTO hoặc tắt đèn.

const now = new Date();
const currentHour = now.getHours();
const telemetry = flow.get('orchidLatestTelemetry');
const relayState = flow.get('orchidRelayState') || {};

// Kiểm tra khung giờ ban đêm: 21h tối đến 6h sáng
const isNightTime = (currentHour >= 21 || currentHour < 6);

if (isNightTime) {
    // Nếu đèn đang bật vào ban đêm, cưỡng bức tắt để bảo vệ lan
    if (relayState.light === 'ON') {
        node.warn('[RULE ĐÈN] Đang trong khung giờ ban đêm (21h-6h). Cưỡng bức tắt đèn.');
        return {
            relay: 'light',
            payload: { mode: 'MANUAL', state: 'OFF', ttl_s: 300 }
        };
    }
    return null;
}

// Trong khung giờ ban ngày (06:00 - 21:00)
if (telemetry && telemetry.light_adc !== undefined) {
    if (telemetry.light_adc >= 2200 && relayState.light !== 'ON') {
        node.log('[RULE ĐÈN] Ban ngày thiếu sáng (ADC ' + telemetry.light_adc + ' >= 2200). Tự động bật đèn 5 phút.');
        return {
            relay: 'light',
            payload: { mode: 'MANUAL', state: 'ON', ttl_s: 300 }
        };
    } else if (telemetry.light_adc <= 1800 && relayState.light === 'ON') {
        node.log('[RULE ĐÈN] Ánh sáng tự nhiên đã đủ (ADC ' + telemetry.light_adc + ' <= 1800). Tự động tắt đèn.');
        return {
            relay: 'light',
            payload: { mode: 'AUTO' }
        };
    }
}
return null;

// BUSINESS RULE 2: QUẠT HỖ TRỢ SAU KHI PHUN SƯƠNG (POST-MIST VENTILATION)
// Khi chu kỳ phun sương vừa kết thúc (mist chuyển từ ON sang OFF):
// - Kích hoạt quạt thông gió trong 60 giây (ttl_s = 60).
// - Mục đích: Làm ráo nhanh các giọt sương đọng trên kẽ lá lan, giảm tối đa nguy cơ nấm mốc và thối nõn.
// - Quy tắc ban đêm: Không cho quạt chạy liên tục suốt đêm.

const trigger = msg.payload;
if (!trigger || trigger.rule !== 'POST_MIST_VENTILATION') return null;

const now = new Date();
const currentHour = now.getHours();

node.log('[RULE QUẠT] Phát hiện kết thúc phun sương. Tự động kích hoạt quạt thông gió trong 60 giây.');

return {
    relay: 'fan',
    payload: {
        mode: 'MANUAL',
        state: 'ON',
        ttl_s: 60
    }
};
